oa_url": "https://dl.acm.org/doi/pdf/10.1145/3774896", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1145/3774896", "doi": "https://doi.org/10.1145/3774896", "is_oa": true, "landing_page_url": "https://doi.org/10.1145/3774896", "pdf_url": "https://dl.acm.org/doi/pdf/10.1145/3774896", "source": {"id": "https://openalex.org/S157921468", "display_name": "ACM Computing Surveys", "issn_l": "0360-0300", "issn": ["0360-0300", "1557-7341"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["cwts-core", "dongbi-a", "jufo-3", "ki-jl-2", "norway-2", "poland-200", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319798", "host_organization_name": "Association for Computing Machinery", "host_organization_lineage": ["https://openalex.org/P4310319798"], "host_organization_lineage_names": ["Association for Computing Machinery"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "ACM Computing Surveys", "raw_type": "journal-article"}, "abstract": "Large language models (LLMs) with billions of parameters exhibit in-context learning abilities, enabling few-shot learning on tasks that the model was not specifically trained for. Traditional models achieve breakthrough performance on language tasks, but do not perform well on basic reasoning benchmarks. However, a new in-context learning approach, Chain-of-thought, has demonstrated strong multi-step reasoning abilities on these benchmarks. The research on LLM reasoning abilities started with the question whether LLMs can solve grade school math word problems, and has expanded to other tasks in the past few years. This article reviews the field of multi-step reasoning with LLMs. We propose a taxonomy that identifies different ways to generate, evaluate, and control multi-step reasoning. We provide an in-depth coverage of core approaches and open problems, and we propose a research agenda for the near future. We find that multi-step reasoning approaches have progressed beyond math word problems, and can now successfully solve challenges in logic, combinatorial games, and robotics, sometimes by first generating code that is then executed by external tools. Many studies in multi-step methods use reinforcement learning for finetuning, external optimization loops, in-context reinforcement learning, and self-reflection."}]", "excerpt_truncated": true, "source_sha256": "e5c339bf4582f4591691fcb86ac1bbf66374c38b1c669d0c15f719d3798136a0", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1093/logcom/exh034", "doi:10.48550/arxiv.2309.02427", "doi:10.1145/3774896", "openalex:W2158415135", "openalex:W4386528753"], "source_candidates": ["https://doi.org/10.1093/logcom/exh034", "https://doi.org/10.48550/arxiv.2309.02427", "https://dl.acm.org/doi/pdf/10.1145/3774896", "https://doi.org/10.1145/3774896"], "source_candidate_identities": {}}
